#include "zpse/huf.h"

#include "zpse/bits.h"
#include "zpse/constants.h"
#include "zpse/status.h"

#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* The four code books and the 11-bit lookups built from them. Generated by
 * tests/benchmarks/huf_train.c; see include/zpse/huf.h for why they are part
 * of the format rather than of the block.
 *
 *   zpse_huf_ctab[t][s]    (code << 4) | nbits   code is bit-REVERSED
 *   zpse_huf_dtab[t][i]    (nbBits << 8) | symbol
 *
 * Two bytes and one symbol per lookup. A two-symbol entry was built first and
 * thrown away: it only fires when BOTH codes fit inside the eleven bits of the
 * window, and an LZ command stream averages about seven bits per symbol, so a
 * pair needs fourteen and the entry almost never has one. Measured on the page
 * corpus it produced a 101% payload -- paying for a 32 KiB table and still
 * decoding one symbol per lookup. One symbol per lookup also stops the padding
 * after a stream's last symbol from mattering: the tail stops at the output
 * end, and the bit count catches a stream that disagreed with its length, so
 * no last-symbol special case is needed.
 *
 * Every symbol has a code in every table (the trainer seeds each count with
 * one), so a lookup can only fail on a corrupt table_id, which the payload
 * parser rejects before a lookup happens. The trainer still fills unreachable
 * prefixes with symbol zero on the longest code, so a table that ever lost
 * completeness would cost eleven bits per lookup rather than loop.
 */
#include "huf_tables.inc"

/* 64 bits of the stream at p, little-endian, zero past `end`. The reader below
 * may look past a stream's last byte; making that read explicit and clamped is
 * what keeps a corrupt payload from walking off the buffer. */
static inline uint64_t huf_read64(const uint8_t *p, const uint8_t *end)
{
    uint64_t v;

    if (p >= end) {
        return 0u;
    }
    if ((size_t)(end - p) >= 8u) {
        memcpy(&v, p, 8u);
#if defined(__BYTE_ORDER__) && (__BYTE_ORDER__ == __ORDER_BIG_ENDIAN__)
        v = __builtin_bswap64(v);
#endif
        return v;
    }
    v = 0u;
    {
        uint32_t i = 0u;

        while (p + i < end) {
            v |= (uint64_t)p[i] << (8u * i);
            i++;
        }
    }
    return v;
}

/* ---- Bit reader ---------------------------------------------------------
 *
 * LSB-first: the window's bit 0 is the next bit of the stream. `bitpos` is how
 * many bits have been handed out, so a refill is one unaligned load at the
 * byte holding `bitpos` followed by a shift -- no per-byte loop and no
 * byte-at-a-time assembly, which is the whole reason the format fixes the bit
 * order. A refill leaves at least 57 usable bits (64 minus the 0..7 bit
 * offset) and the longest lookup consumes eleven, so a refill below 19 always
 * leaves a whole lookup available. The hot loop does not use this: it refills
 * on a fixed cadence instead, so that no branch sits in the decode path. */
typedef struct HuffRd {
    const uint8_t *start;
    const uint8_t *end;
    uint32_t bitpos;
    uint64_t acc;
    int32_t have;
} HuffRd;

static inline void huf_rd_fill(HuffRd *r)
{
    uint32_t by = r->bitpos >> 3;
    uint32_t sh = r->bitpos & 7u;
    uint32_t total = (uint32_t)(r->end - r->start) * 8u;
    uint32_t left = (total > r->bitpos) ? (total - r->bitpos) : 0u;
    uint32_t room = 64u - sh;

    r->acc = huf_read64(r->start + by, r->end) >> sh;
    r->have = (int32_t)((left < room) ? left : room);
}

/* Bytes stream k of an inner_len-byte payload codes to, split four ways. */
static inline uint32_t huf_share(uint32_t inner_len)
{
    return inner_len / (uint32_t)ZPSE_HUF_STREAMS;
}

static inline uint32_t huf_stream_len(uint32_t inner_len, uint32_t k)
{
    uint32_t sh = huf_share(inner_len);

    return (k + 1u < (uint32_t)ZPSE_HUF_STREAMS) ? sh
                                                 : (inner_len - sh * 3u);
}

/* One byte in this many is what ranks the four code books. See the sample
 * histogram in zpse_huf_encode: the choice is a ranking, the sizes are exact,
 * and only the ranking can afford to look at part of the block. */
#ifndef ZPSE_HUF_SAMPLE
#define ZPSE_HUF_SAMPLE 8u
#endif

/* ---- Encoding -----------------------------------------------------------
 *
 * Two passes over the payload and no more:
 *
 *   1. one strided sample histogram, which ranks the four code books. It is
 *      deliberately not a count of every byte: a full scatter histogram costs
 *      about two cycles per byte on this data, and ranking four fixed tables
 *      does not need every symbol. See the note at the histogram for what the
 *      header's exact lengths use instead.
 *
 *   2. the codes themselves, five at a time, into a 64-bit shift register
 *      that one eight-byte store flushes.
 *
 * Three details in the writer are there because the obvious versions measured
 * badly:
 *
 *   Positions are a prefix sum, not a running total. The shift amount for each
 *   code is the sum of the lengths of the codes before it, which is four
 *   independent adds feeding five shifts that can then issue in parallel.
 *   Accumulating one `pos` through the five codes instead makes every shift
 *   wait for the previous symbol's table load.
 *
 *   The streams are coded one after another, not interleaved. Four at once
 *   needs twenty live values -- four cursors, four sources, four ends, four
 *   accumulators, four bit offsets -- and no x86-64 register file holds that;
 *   the compiler spills, and the interleaved version measured slower than this
 *   one. One stream needs six values, the table loads for consecutive steps do
 *   not depend on the bit position at all, and so the loop runs at the load
 *   port rather than at whatever the spill traffic allows.
 *
 *   The flush overwrites. Five codes are at most fifty-five bits (the longest
 *   code is eleven), so the store of eight bytes at the cursor can run up to
 *   seven bytes past what the stream has really produced. Those bytes belong
 *   to the next stream, which is coded afterwards and overwrites them from its
 *   own start, so the slop never survives. The last stream's overrun does
 *   leave the payload, and that slack cannot be removed without giving up the
 *   whole-word store: the exact end of a stream is only known once it has been
 *   written, so a writer that must never store past it has to know the lengths
 *   first -- which is the extra pass this encoder does not make. Eight bytes
 *   per stream is the price: the capacity test in zpse_huf_encode reserves it,
 *   and no byte the caller reads ever depends on it.
 */

static inline void huf_store8(uint8_t *p, uint64_t v)
{
#if defined(__BYTE_ORDER__) && (__BYTE_ORDER__ == __ORDER_BIG_ENDIAN__)
    v = __builtin_bswap64(v);
#endif
    memcpy(p, &v, 8u);
}

/* One step: five codes, positions from a prefix sum, one eight-byte store.
 *
 * The codes and the lengths are two tables rather than one packed entry. A
 * step needs both for every symbol, so loading them separately costs one more
 * load and removes a mask and a shift from each of the five codes: measured
 * at the same output, 2.79 -> 1.86 cycles per byte. The loop is bound by uops
 * per symbol at that point -- a byte load, two table loads, one shift, one or
 * and four fifths of a prefix-sum add -- so a third table load would not pay
 * and the tinier operand forms do not help. */
#define ZPSE_HUF_PUT5(C, Q, S, P, CD, LT)                                   \
    do {                                                                    \
        uint32_t l0_ = (LT)[(S)[0]];                                        \
        uint32_t l1_ = (LT)[(S)[1]];                                        \
        uint32_t l2_ = (LT)[(S)[2]];                                        \
        uint32_t l3_ = (LT)[(S)[3]];                                        \
        uint32_t l4_ = (LT)[(S)[4]];                                        \
        uint32_t q1_ = (Q) + l0_;                                           \
        uint32_t q2_ = q1_ + l1_;                                           \
        uint32_t q3_ = q2_ + l2_;                                           \
        uint32_t q4_ = q3_ + l3_;                                           \
        uint32_t tot_ = q4_ + l4_;                                          \
                                                                            \
        (C) |= ((uint64_t)(CD)[(S)[0]] << (Q)) |                            \
               ((uint64_t)(CD)[(S)[1]] << q1_) |                            \
               ((uint64_t)(CD)[(S)[2]] << q2_) |                            \
               ((uint64_t)(CD)[(S)[3]] << q3_) |                            \
               ((uint64_t)(CD)[(S)[4]] << q4_);                             \
        huf_store8((P), (C));                                               \
        {                                                                   \
            uint32_t nb_ = tot_ >> 3;                                       \
                                                                            \
            (P) += nb_;                                                     \
            (C) >>= nb_ * 8u;                                               \
        }                                                                   \
        (Q) = tot_ & 7u;                                                    \
    } while (0)

/* Code one stream and return the cursor past its last byte. */
static uint8_t *huf_enc_stream(const uint16_t *cd, const uint8_t *lt,
                               const uint8_t *src, uint32_t len, uint8_t *dst)
{
    uint8_t *p = dst;
    uint64_t acc = 0u;
    uint32_t pos = 0u;
    uint32_t i = 0u;

    for (; i + 5u <= len; i += 5u) {
        ZPSE_HUF_PUT5(acc, pos, src + i, p, cd, lt);
    }
    for (; i < len; i++) {
        acc |= (uint64_t)cd[src[i]] << pos;
        pos += lt[src[i]];
    }
    huf_store8(p, acc);
    return p + ((pos + 7u) >> 3);
}

uint32_t zpse_huf_encode(const uint8_t *in, uint32_t n, uint8_t *dst,
                         uint32_t cap, uint8_t inner_form)
{
    uint16_t hist[ZPSE_HUF_SYMBOLS];
    uint16_t code[ZPSE_HUF_SYMBOLS];
    uint8_t lt[ZPSE_HUF_SYMBOLS];
    uint32_t blen[ZPSE_HUF_STREAMS];
    const uint16_t *ct;
    uint32_t best = 0u;
    uint64_t best_cost = UINT64_MAX;
    uint32_t total;
    uint32_t t;
    uint32_t k;
    uint32_t s;

    if (in == 0 || dst == 0) {
        return 0u;
    }
    if (n < (uint32_t)ZPSE_HUF_MIN_INNER ||
        n > (uint32_t)ZPSE_HUF_MAX_INNER) {
        return 0u;
    }
    if (cap < (uint32_t)ZPSE_HUF_MIN_PAYLOAD) {
        return 0u;
    }
    /* The inner form is the caller's business, but a payload that names no LZ
     * form is one the decoder would refuse, so it is not written. */
    if (inner_form != (uint8_t)ZPSE_B_LZ &&
        inner_form != (uint8_t)ZPSE_B_LZ2 &&
        inner_form != (uint8_t)ZPSE_B_LZ_HEX) {
        return 0u;
    }

    /* One histogram, over a strided sample -- not one per stream over every
     * byte.
     *
     * What the table choice needs is a RANKING of four fixed code books, and
     * one byte in eight ranks them; what the header needs is the exact length
     * of each stream, and that comes from the bit count below instead.
     * Measured on this host, a full scatter histogram over the payload costs
     * about two cycles per byte -- increments to a hot bin serialise, and four
     * stream copies only take the worst of it off (2.52 sequential, 2.00
     * interleaved) -- while a stride of eight costs a quarter of that and the
     * exact bit count costs under one. Splitting the two jobs by what they
     * actually need is worth about a cycle per byte.
     *
     * The sample is deterministic: every build, every SIMD level and every
     * worker counts the same bytes of the same block, so a block is still a
     * function of its own bytes alone. */
    memset(hist, 0, sizeof hist);
    {
        uint32_t i;

        for (i = 0; i < n; i += (uint32_t)ZPSE_HUF_SAMPLE) {
            hist[in[i]]++;
        }
    }

    /* Pick a table by pricing all four against the sampled counts: 4 x 256
     * multiply-adds. A symbol with no code in a table makes that table
     * unusable for this block rather than free, so the test is inside the
     * loop. Ties go to the lowest index, because "the first one that ties" is
     * the only rule that cannot change between builds. */
    {
        for (t = 0; t < (uint32_t)ZPSE_HUF_TABLES; t++) {
            const uint16_t *tab = zpse_huf_ctab[t];
            uint64_t cost = 0u;
            uint32_t bad = 0u;

            for (s = 0; s < (uint32_t)ZPSE_HUF_SYMBOLS; s++) {
                uint32_t h = hist[s];

                if (h != 0u) {
                    uint32_t nb = (uint32_t)(tab[s] & 15u);

                    if (nb == 0u) {
                        bad = 1u;
                        break;
                    }
                    cost += (uint64_t)h * (uint64_t)nb;
                }
            }
            if (bad == 0u && cost < best_cost) {
                best_cost = cost;
                best = t;
            }
        }
    }
    if (best_cost == UINT64_MAX) {
        return 0u;
    }
    ct = zpse_huf_ctab[best];
    /* The chosen table as two arrays, which is the shape the coding loop
     * wants; 256 iterations per block, against a pass that touches every
     * byte. */
    for (s = 0; s < (uint32_t)ZPSE_HUF_SYMBOLS; s++) {
        code[s] = (uint16_t)(ct[s] >> 4);
        lt[s] = (uint8_t)(ct[s] & 15u);
    }

    /* How the header's four lengths and the total are come by, in the order
     * that keeps the pass count down.
     *
     * The coding loop already forms the bit total of every five symbols it
     * writes, so a stream's encoded length is what the write itself produced.
     * So when the caller's capacity can absorb the worst case for this
     * payload, the streams are written first and the twelve-byte header last,
     * and the bit count never runs. The worst case is every symbol taking the
     * longest code a table has, eleven bits: the header, eleven bits per
     * payload byte, and the eight-byte store slop of each stream.
     *
     * When that bound does not fit -- a payload near the 64 KiB staging
     * buffer, where eleven bits a symbol could not be stored -- the lengths
     * are counted first and nothing is written until the exact size is known.
     * That is the case the contract in huf.h describes. */
    {
        uint64_t worst = (uint64_t)ZPSE_HUF_HDR;
        uint32_t i;

        for (i = 0; i < (uint32_t)ZPSE_HUF_STREAMS; i++) {
            worst += (uint64_t)((huf_stream_len(n, i) *
                                 (uint32_t)ZPSE_HUF_MAX_LEN + 7u) / 8u) + 8u;
        }
        if (worst > (uint64_t)cap) {
            uint32_t sh = huf_share(n);
            uint32_t b0 = 0u, b1 = 0u, b2 = 0u, b3 = 0u;

            for (i = 0; i < sh; i++) {
                b0 += (uint32_t)lt[in[i]];
                b1 += (uint32_t)lt[in[sh + i]];
                b2 += (uint32_t)lt[in[2u * sh + i]];
                b3 += (uint32_t)lt[in[3u * sh + i]];
            }
            for (i = 4u * sh; i < n; i++) {
                b3 += (uint32_t)lt[in[i]];
            }
            blen[0] = (b0 + 7u) >> 3;
            blen[1] = (b1 + 7u) >> 3;
            blen[2] = (b2 + 7u) >> 3;
            blen[3] = (b3 + 7u) >> 3;
            total = (uint32_t)ZPSE_HUF_HDR;
            for (k = 0; k < (uint32_t)ZPSE_HUF_STREAMS; k++) {
                /* The header carries each length in sixteen bits, so a payload
                 * whose quarter codes past 64 KiB cannot be described. */
                if (blen[k] > 0xFFFFu) {
                    return 0u;
                }
                total += blen[k];
            }
            /* Eight bytes of slack: the last stream's flush stores a whole
             * word and may run past the payload. Earlier streams' slop is
             * overwritten by the stream that follows them. */
            if (total + 8u > cap) {
                return 0u;
            }
        }
    }

    {
        uint8_t *p = dst + (uint32_t)ZPSE_HUF_HDR;
        uint32_t off = 0u;

        for (k = 0; k < (uint32_t)ZPSE_HUF_STREAMS; k++) {
            uint32_t len = huf_stream_len(n, k);
            uint8_t *st = p;

            p = huf_enc_stream(code, lt, in + off, len, p);
            blen[k] = (uint32_t)(p - st);
            off += len;
        }
        total = (uint32_t)(p - dst);
    }

    dst[0] = (uint8_t)best;
    dst[1] = inner_form;
    zpse_store_u32le(dst + 2, n);
    zpse_store_u16le(dst + 6, (uint16_t)blen[0]);
    zpse_store_u16le(dst + 8, (uint16_t)blen[1]);
    zpse_store_u16le(dst + 10, (uint16_t)blen[2]);
    return total;
}

/* ---- Decoding -----------------------------------------------------------
 *
 * Four streams, four lookups in flight, one symbol per lookup.
 *
 * The shape follows huff0 (Zstd's entropy coder), and every part of it exists
 * for a measured reason:
 *
 *   1. Four independent bit readers, not one. A Huffman bit stream is serial
 *      by construction -- one symbol's length decides where the next symbol
 *      starts -- so no vector lane can help, and running streams side by side
 *      is the only source of instruction-level work the format has.
 *
 *   2. No bounds check in the loop. An outer loop prices how many runs of
 *      five lookups fit, from the output room left and the input left; the
 *      inner loop then does exactly that many with no per-symbol test.
 *
 *   3. Refill on a fixed cadence, not on a test. A lookup consumes at most
 *      ZPSE_HUF_MAX_LEN (11) bits, so five lookups consume 55, and a refill
 *      that leaves 57 always covers exactly five. The window is reloaded where
 *      the source says it is, instead of where a branch predicts it should be.
 *
 *   4. Three live values per stream -- window, bit position, output cursor.
 *      Seven per stream (window, bits left, bit position, output cursor,
 *      output end, stream start, stream end) does not fit in sixteen
 *      registers, and a compiler's answer to that is to spill all of them: a
 *      first version that kept seven measured 470 MB/s here and moved 122
 *      values to the stack. This one keeps three and reads the stream bounds
 *      from the stack once per run.
 *
 * One symbol per lookup, not two, because of what an LZ payload looks like.
 * A two-symbol entry only fires when both codes fit in eleven bits, which
 * needs both symbols to be short; an LZ command stream averages around seven
 * bits per symbol, so a pair needs fourteen and the entry almost never has
 * one. A two-symbol table was measured on this corpus and produced a 101%
 * payload -- it paid for the wider table and decoded one symbol per lookup
 * anyway. Two-byte entries also halve the tables, from 32 KiB to 16 KiB.
 */

/* How many lookups a refill covers: 5 * 11 = 55 bits, and a refill leaves at
 * least 57 because it is taken at a byte boundary of a 64-bit window. */
#define ZPSE_HUF_RUN 5u

/* Bytes one run can consume: 55 bits, rounded up. The margin is what keeps the
 * loop away from the zero padding at the end of a stream -- a run never starts
 * with less than this many bytes left, so the phantom symbol the padding can
 * describe is never decoded here, where nothing is checking for it. */
#define ZPSE_HUF_RUN_IN 7u
#define ZPSE_HUF_RUN_MARGIN 10u

static inline uint64_t huf_load8(const uint8_t *p)
{
    uint64_t v;

    memcpy(&v, p, 8u);
#if defined(__BYTE_ORDER__) && (__BYTE_ORDER__ == __ORDER_BIG_ENDIAN__)
    v = __builtin_bswap64(v);
#endif
    return v;
}

/* Did this stream consume its own bytes and nothing more? The last byte is
 * zero-padded, so between nought and seven bits of it are legitimately
 * unused; anything outside that window is a stream that disagreed with the
 * length the header gave it. */
static int huf_stream_ok(const HuffRd *r)
{
    uint32_t total = (uint32_t)(r->end - r->start) * 8u;

    return (r->bitpos <= total) && (r->bitpos + 8u > total);
}

/* How many runs this stream can still afford before a refill could read or
 * consume past its end. */
static inline size_t huf_room(const uint8_t *s, const uint8_t *e,
                              uint32_t bitpos)
{
    size_t seg = (size_t)(e - s);
    size_t off = (size_t)(bitpos >> 3);

    if (off + (size_t)ZPSE_HUF_RUN_MARGIN >= seg) {
        return 0u;
    }
    return (seg - off - (size_t)ZPSE_HUF_RUN_MARGIN) / (size_t)ZPSE_HUF_RUN_IN;
}

/* One lookup: the entry is (nbBits << 8) | symbol, so the store is one byte at
 * a cursor that advances by one -- the store address never depends on the
 * table load, which is what lets the stores run ahead of the decode. */
#define ZPSE_HUF_LOOK(A, B, O, DT)                                          \
    do {                                                                    \
        uint32_t e_ = (DT)[(uint32_t)((A) & 0x7FFu)];                       \
                                                                            \
        (O)[0] = (uint8_t)e_;                                               \
        (O) += 1;                                                           \
        (B) += e_ >> 8;                                                     \
        (A) >>= e_ >> 8;                                                    \
    } while (0)

/* One run: refill the window, then five lookups. */
#define ZPSE_HUF_RUN_DO(A, B, S, O, DT)                                     \
    do {                                                                    \
        (A) = huf_load8((S) + (size_t)((B) >> 3)) >> ((B) & 7u);            \
        ZPSE_HUF_LOOK(A, B, O, DT);                                         \
        ZPSE_HUF_LOOK(A, B, O, DT);                                         \
        ZPSE_HUF_LOOK(A, B, O, DT);                                         \
        ZPSE_HUF_LOOK(A, B, O, DT);                                         \
        ZPSE_HUF_LOOK(A, B, O, DT);                                         \
    } while (0)

/* Finish one stream after the runs. The window is rebuilt from the bit
 * position, so nothing but the cursor and the count has to leave the loop. */
static int huf_finish(const uint16_t *dt, const uint8_t *s, const uint8_t *e,
                      uint32_t bitpos, uint8_t *o, uint8_t *oe)
{
    HuffRd r;

    r.start = s;
    r.end = e;
    r.bitpos = bitpos;
    r.acc = 0u;
    r.have = 0;
    huf_rd_fill(&r);
    while (o < oe) {
        uint32_t ent;
        uint32_t nb;

        if (r.have < (int32_t)ZPSE_HUF_MAX_LEN + 8) {
            huf_rd_fill(&r);
        }
        ent = dt[(uint32_t)(r.acc & 0x7FFu)];
        o[0] = (uint8_t)ent;
        o += 1;
        nb = ent >> 8;
        r.acc >>= nb;
        r.have -= (int32_t)nb;
        r.bitpos += nb;
    }
    return huf_stream_ok(&r);
}

static int huf_decode4(const uint16_t *dt, const uint8_t *ib[ZPSE_HUF_STREAMS],
                       const uint8_t *ie[ZPSE_HUF_STREAMS],
                       uint8_t *ob[ZPSE_HUF_STREAMS],
                       uint8_t *oe[ZPSE_HUF_STREAMS])
{
    const uint8_t *i0 = ib[0];
    const uint8_t *i1 = ib[1];
    const uint8_t *i2 = ib[2];
    const uint8_t *i3 = ib[3];
    uint8_t *p0 = ob[0];
    uint8_t *p1 = ob[1];
    uint8_t *p2 = ob[2];
    uint8_t *p3 = ob[3];
    uint64_t a0 = 0u;
    uint64_t a1 = 0u;
    uint64_t a2 = 0u;
    uint64_t a3 = 0u;
    uint32_t b0 = 0u;
    uint32_t b1 = 0u;
    uint32_t b2 = 0u;
    uint32_t b3 = 0u;

    for (;;) {
        size_t g = (size_t)(oe[0] - p0) / (size_t)ZPSE_HUF_RUN;
        size_t r;
        size_t i;

        r = (size_t)(oe[1] - p1) / (size_t)ZPSE_HUF_RUN;
        if (r < g) {
            g = r;
        }
        r = (size_t)(oe[2] - p2) / (size_t)ZPSE_HUF_RUN;
        if (r < g) {
            g = r;
        }
        r = (size_t)(oe[3] - p3) / (size_t)ZPSE_HUF_RUN;
        if (r < g) {
            g = r;
        }
        r = huf_room(i0, ie[0], b0);
        if (r < g) {
            g = r;
        }
        r = huf_room(i1, ie[1], b1);
        if (r < g) {
            g = r;
        }
        r = huf_room(i2, ie[2], b2);
        if (r < g) {
            g = r;
        }
        r = huf_room(i3, ie[3], b3);
        if (r < g) {
            g = r;
        }
        if (g == 0u) {
            break;
        }
        for (i = 0; i < g; i++) {
            ZPSE_HUF_RUN_DO(a0, b0, i0, p0, dt);
            ZPSE_HUF_RUN_DO(a1, b1, i1, p1, dt);
            ZPSE_HUF_RUN_DO(a2, b2, i2, p2, dt);
            ZPSE_HUF_RUN_DO(a3, b3, i3, p3, dt);
        }
    }
    ob[0] = p0;
    ob[1] = p1;
    ob[2] = p2;
    ob[3] = p3;
    return huf_finish(dt, i0, ie[0], b0, p0, oe[0]) &
           huf_finish(dt, i1, ie[1], b1, p1, oe[1]) &
           huf_finish(dt, i2, ie[2], b2, p2, oe[2]) &
           huf_finish(dt, i3, ie[3], b3, p3, oe[3]);
}

int zpse_huf_decode(const uint8_t *in, uint32_t in_len, uint8_t *out,
                    uint32_t out_cap, uint32_t *inner_len_out,
                    uint8_t *inner_form_out)
{
    uint32_t seg[ZPSE_HUF_STREAMS];
    uint32_t inner_len;
    uint32_t tid;
    uint8_t form;
    const uint8_t *ip[ZPSE_HUF_STREAMS];
    const uint8_t *ie[ZPSE_HUF_STREAMS];
    uint8_t *op[ZPSE_HUF_STREAMS];
    uint8_t *oe[ZPSE_HUF_STREAMS];
    uint32_t k;
    const uint8_t *p;
    uint8_t *q;

    if (in == 0 || out == 0 || inner_len_out == 0 || inner_form_out == 0) {
        return ZPSE_BAD_ARG;
    }
    if (in_len < (uint32_t)ZPSE_HUF_MIN_PAYLOAD) {
        return ZPSE_BAD_BLOCK_SIZE;
    }
    tid = in[0];
    form = in[1];
    inner_len = zpse_load_u32le(in + 2);
    if (tid >= (uint32_t)ZPSE_HUF_TABLES) {
        return ZPSE_BAD_HUF;
    }
    if (form != (uint8_t)ZPSE_B_LZ && form != (uint8_t)ZPSE_B_LZ2 &&
        form != (uint8_t)ZPSE_B_LZ_HEX) {
        return ZPSE_BAD_HEADER;
    }
    if (inner_len < (uint32_t)ZPSE_HUF_MIN_INNER ||
        inner_len > (uint32_t)ZPSE_HUF_MAX_INNER) {
        return ZPSE_BAD_HEADER;
    }
    if (inner_len > out_cap) {
        return ZPSE_OUTPUT_OVERFLOW;
    }
    seg[0] = zpse_load_u16le(in + 6);
    seg[1] = zpse_load_u16le(in + 8);
    seg[2] = zpse_load_u16le(in + 10);
    /* Stream 3 takes whatever is left, so the three written lengths are what
     * the parser has to check: they must leave a non-empty last stream and
     * must not themselves run past the payload. */
    {
        uint32_t used = (uint32_t)ZPSE_HUF_HDR + seg[0] + seg[1] + seg[2];

        if (seg[0] == 0u || seg[1] == 0u || seg[2] == 0u) {
            return ZPSE_BAD_HUF;
        }
        if (used >= in_len) {
            return ZPSE_BAD_HUF;
        }
        seg[3] = in_len - used;
    }

    p = in + (uint32_t)ZPSE_HUF_HDR;
    q = out;
    for (k = 0; k < (uint32_t)ZPSE_HUF_STREAMS; k++) {
        ip[k] = p;
        ie[k] = p + seg[k];
        op[k] = q;
        oe[k] = q + huf_stream_len(inner_len, k);
        p += seg[k];
        q = oe[k];
    }

    if (!huf_decode4(zpse_huf_dtab[tid], ip, ie, op, oe)) {
        return ZPSE_BAD_HUF;
    }

    *inner_len_out = inner_len;
    *inner_form_out = form;
    return ZPSE_OK;
}
